package main

import "fmt"

func main() {
	// 球员身高字典，请勿改变
	team := map[string]float32{
		"P1": 1.98,
		"P2": 2.05,
		"P3": 1.89,
		"P4": 2.0,
		"P5": 2.11}
	var sum float32 = 0.0
	for _, x := range team {
		sum += x
	}
	fmt.Println(sum / 5)
}
